test('satisfies: matching cases', () => {
  for (const [ver, range] of yes) assert.strictEqual(satisfies(ver, range), true, `${ver} should satisfy "${range}"`);
});

test('satisfies: non-matching and invalid cases', () => {
  for (const [ver, range] of no) assert.strictEqual(satisfies(ver, range), false, `${ver} should not satisfy "${range}"`);
});

test('satisfies: never throws', () => {
  for (const x of [{}, [], Symbol('s'), () => 1, NaN]) {
    assert.doesNotThrow(() => satisfies(x, x));
    assert.strictEqual(satisfies('1.0.0', x), false);
  }
});

test('satisfies: huge numbers compare exactly', () => {
  assert.strictEqual(satisfies('99999999999999999999.0.0', '>=99999999999999999998.0.0'), true);
  assert.strictEqual(satisfies('9007199254740993.0.0', '9007199254740992.0.0'), false);
});
